			firstBodyToken = sourceCode.getTokenBefore(firstBodyToken);
			lastBodyToken = sourceCode.getTokenAfter(lastBodyToken);
		}

		offsets.setDesiredOffsets(
			[firstBodyToken.range[0], lastBodyToken.range[1]],
			lastParentToken,
			1,
		);
