				options.SwitchCase = opts.SwitchCase || 0;

				if (typeof opts.VariableDeclarator === "number") {
					options.VariableDeclarator = {
						var: opts.VariableDeclarator,
						let: opts.VariableDeclarator,
						const: opts.VariableDeclarator,
