				} else if (typeof opts.VariableDeclarator === "object") {
					Object.assign(options.VariableDeclarator, opts.VariableDeclarator);
				}

				assignOption(opts, "outerIIFEBody", options);
				assignOption(opts, "MemberExpression", options);

				if (typeof opts.FunctionDeclaration === "object") {
					Object.assign(options.FunctionDeclaration, opts.FunctionDeclaration);
				}
				if (typeof opts.FunctionExpression === "object") {
					Object.assign(options.FunctionExpression, opts.FunctionExpression);
				}
				if (typeof opts.CallExpression === "object") {
					Object.assign(options.CallExpression, opts.CallExpression);
				}

				assignSimpleOption(opts, "ArrayExpression", options);
				assignSimpleOption(opts, "ObjectExpression", options);
			}
		}
