		outerIIFEBody: null,
		FunctionDeclaration: {
			parameters: DEFAULT_PARAMETER_INDENT,
			body: DEFAULT_FUNCTION_BODY_INDENT,
		},
		FunctionExpression: {
			parameters: DEFAULT_PARAMETER_INDENT,
			body: DEFAULT_FUNCTION_BODY_INDENT,
		},
		CallExpression: { arguments: DEFAULT_PARAMETER_INDENT },
		ArrayExpression: 1,
		ObjectExpression: 1,
	};

	if (!configOptions.length) {
		return options;
