/**
 * Validates and normalizes options for the wrapped CLIEngine instance.
 * @param {ESLintOptions} options The options to process.
 * @throws {ESLintInvalidOptionsError} If of any of a variety of type errors.
 * @returns {ESLintOptions} The normalized options.
 */
function processOptions(options = {}) {
	const {
		allowInlineConfig = true,
		baseConfig = null,
		cache = false,
		cacheLocation = ".eslintcache",
		cacheStrategy = "metadata",
		concurrency = "off",
		cwd = process.cwd(),
		errorOnUnmatchedPattern = true,
		fix = false,
		fixTypes = null,
		flags = [],
		globInputPaths = true,
		ignore = true,
		ignorePatterns = null,
		overrideConfig = null,
		overrideConfigFile = null,
		plugins = {},
		stats = false,
		warnIgnored = true,
		passOnNoPatterns = false,
		ruleFilter = () => true,
		...unknownOptions
	} = options;

	const errors = [];

	validateUnknownOptions(errors, unknownOptions);
	validateAllowInlineConfig(errors, allowInlineConfig);
	validateBaseConfig(errors, baseConfig);
	validateCache(errors, cache);
	validateCacheLocation(errors, cacheLocation);
	validateCacheStrategy(errors, cacheStrategy);
	validateConcurrency(errors, concurrency);
	validateCwd(errors, cwd);
	validateErrorOnUnmatchedPattern(errors, errorOnUnmatchedPattern);
	validateFix(errors, fix);
	validateFixTypes(errors, fixTypes);
	validateFlags(errors, flags);
	validateGlobInputPaths(errors, globInputPaths);
	validateIgnore(errors, ignore);
	validateIgnorePatterns(errors, ignorePatterns);
	validateOverrideConfig(errors, overrideConfig);
	validateOverrideConfigFile(errors, overrideConfigFile);
	validatePassOnNoPatterns(errors, passOnNoPatterns);
	validatePlugins(errors, plugins);
	validateStats(errors, stats);
	validateWarnIgnored(errors, warnIgnored);
	validateRuleFilter(errors, ruleFilter);

	if (errors.length > 0) {
		throw new ESLintInvalidOptionsError(errors);
	}

	return {
		allowInlineConfig,
		baseConfig,
		cache,
		cacheLocation,
		cacheStrategy,
		concurrency,

		// when overrideConfigFile is true that means don't do config file lookup
		configFile: overrideConfigFile === true ? false : overrideConfigFile,
		overrideConfig,
		cwd: path.normalize(cwd),
		errorOnUnmatchedPattern,
		fix,
		fixTypes,
		flags: [...flags],
		globInputPaths,
		ignore,
		ignorePatterns,
		stats,
		passOnNoPatterns,
		warnIgnored,
		ruleFilter,
	};
}

