		it("should offset only column if lineStart is 1 and columnStart is 0", () => {
			const loc = { line: 2, column: 0, endLine: 2, endColumn: 3 };
			const lang = { columnStart: 0, lineStart: 1 };
			const result = updateLocationInformation(loc, lang);

