        forceValidation: state.forceValidation,
        value: cb(state.value),
      }
    })
  }, [])

  const handleDone = useCallback(() => {
    const element = elements.at(modalState.index)
    if (!element) return
    if (!clientSideValidateProp(element.schema, modalState.value)) {
      setModalState(state => ({
