      return
    }
    previewPropsOnChange(modalState.value, element)
    setModalState('closed')
  }, [elements, modalState])

  return (
    <Field label={label} labelElementType="span">
      {groupProps => (
        <VStack gap="medium" role="group" minWidth={0} {...groupProps}>
          <ArrayFieldListView
            {...props}
            aria-label={label ?? ''}
            onOpenItem={handleOpenItem}
