    this.Client.launchBus(function (err, bus) {
      if (err) {
        console.error('Error launchBus: ' + err);
        that.exitCli(cst.ERROR_EXIT);
        return;
      }

      bus.on('log:*', function(type, data) {
        Dashboard.log(type, data);
