'use strict';

/**
 * Module dependencies
 */

// Public node modules.
const _ = require('lodash');
const mongoose = require('mongoose');

// Utils
const {
  models: { getValuePrimaryKey },
} = require('strapi-utils');

const transformToArrayID = (array, pk) => {
  if (_.isArray(array)) {
    return array
      .map(value => value && (getValuePrimaryKey(value, pk) || value))
      .filter(n => n)
      .map(val => _.toString(val));
  }

  return transformToArrayID([array]);
};

const removeUndefinedKeys = (obj = {}) => _.pickBy(obj, _.negate(_.isUndefined));

const addRelationMorph = async (model, params, { session = null } = {}) => {
  const { id, alias, refId, ref, field, filter } = params;

  await model.updateMany(
    {
      [model.primaryKey]: id,
    },
    {
      $push: {
        [alias]: {
          ref: new mongoose.Types.ObjectId(refId),
          kind: ref,
          [filter]: field,
        },
      },
    },
    { session }
  );
};

const removeRelationMorph = async (model, params, { session = null } = {}) => {
  const { alias } = params;

  let opts;
  // if entry id is provided simply query it
  if (params.id) {
    opts = {
      _id: params.id,
    };
  } else {
    opts = {
      [alias]: {
        $elemMatch: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    };
  }

  await model.updateMany(
    opts,
    {
      $pull: {
        [alias]: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    },
    { session }
  );
};

/**
 * Extracts the ref model and handles relation updates for morph associations
 * @param {Object} association - Association definition
 * @param {Object} entry - Current entry
 * @param {Object} obj - Morph relation object
 * @param {Object} params - Update parameters
 * @param {Object} session - Mongoose session
 * @returns {Promise<void>}
 */
const handleMorphRelationUpdate = async (association, entry, obj, params, session) => {
  const refModel = strapi.db.getModel(obj.ref, obj.source);
  const refId = new mongoose.Types.ObjectId(obj.refId);

  const reverseAssoc = refModel.associations?.find(assoc => assoc.alias === obj.field);

  if (reverseAssoc?.nature === 'oneToManyMorph') {
    await removeRelationMorph(
      this,
      {
        alias: association.alias,
        ref: obj.kind || refModel.globalId,
        refId,
        field: obj.field,
        filter: association.filter,
      },
      { session }
    );

    await addRelationMorph(
      this,
      {
        id: entry[this.primaryKey],
        alias: association.alias,
        ref: obj.kind || refModel.globalId,
        refId,
        field: obj.field,
        filter: association.filter,
      },
      { session }
    );

    await refModel.updateMany(
      {
        [refModel.primaryKey]: refId,
      },
      {
        [obj.field]: new mongoose.Types.ObjectId(entry[this.primaryKey]),
      },
      { session }
    );
  } else {
    await addRelationMorph(
      this,
      {
        id: entry[this.primaryKey],
        alias: association.alias,
        ref: obj.kind || refModel.globalId,
        refId,
        field: obj.field,
        filter: association.filter,
      },
      { session }
    );

    await refModel.updateMany(
      {
        [refModel.primaryKey]: refId,
      },
      {
        $push: { [obj.field]: new mongoose.Types.ObjectId(entry[this.primaryKey]) },
      },
      { session }
    );
  }
};

/**
 * Processes manyMorph associations for update operations
 * @param {Object} association - Association definition
 * @param {Object} entry - Current entry
 * @param {Array} newValue - New relation values
 * @param {Object} params - Update parameters
 * @param {Object} session - Mongoose session
 * @returns {Promise<void>}
 */
const processManyMorphRelations = async (association, entry, newValue, params, session) => {
  const relationUpdates = [];

  for (const obj of newValue) {
    relationUpdates.push(
      handleMorphRelationUpdate.call(this, association, entry, obj, params, session)
    );
  }

  await Promise.all(relationUpdates);
};

/**
 * Processes oneToManyMorph associations for update operations
 * @param {Object} association - Association definition
 * @param {Object} entry - Current entry
 * @param {Array|Object} currentValue - Current relation values
 * @param {Array|Object} newValue - New relation values
 * @param {Object} details - Attribute details
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated values object
 */
const processOneToManyMorphRelations = (association, entry, currentValue, newValue, details, session) => {
  const currentIds = transformToArrayID(currentValue, this.primaryKey);
  const newIds = transformToArrayID(newValue, this.primaryKey);

  const toAdd = _.difference(newIds, currentIds);
  const toRemove = _.difference(currentIds, newIds);

  const model = strapi.db.getModel(details.model || details.collection, details.plugin);

  const acc = {};
  _.set(acc, association.alias, Array.isArray(newValue) ? newIds : newIds[0]);

  const addPromise = Promise.all(
    toAdd.map(id => {
      return addRelationMorph(
        model,
        {
          id,
          alias: association.via,
          ref: this.globalId,
          refId: entry._id,
          field: association.alias,
          filter: association.filter,
        },
        { session }
      );
    })
  );

  const relationUpdates = [addPromise];

  toRemove.forEach(id => {
    relationUpdates.push(
      removeRelationMorph(
        model,
        {
          id,
          alias: association.via,
          ref: this.globalId,
          refId: entry._id,
          field: association.alias,
          filter: association.filter,
        },
        { session }
      )
    );
  });

  return { acc, relationUpdates };
};

module.exports = {
  async update(params, { session = null } = {}) {
    const relationUpdates = [];
    const populate = this.associations.map(x => x.alias);
    const primaryKeyValue = getValuePrimaryKey(params, this.primaryKey);

    const entry = await this.findOne({ [this.primaryKey]: primaryKeyValue })
      .session(session)
      .populate(populate)
      .lean();

    // Only update fields which are on this document.
    const values = Object.keys(removeUndefinedKeys(params.values)).reduce((acc, attribute) => {
      const currentValue = entry[attribute];
      const newValue = params.values[attribute];

      const association = this.associations.find(x => x.alias === attribute);

      const details = this._attributes[attribute];

      // set simple attributes
      if (!association && _.get(details, 'isVirtual') !== true) {
        return _.set(acc, attribute, newValue);
      }

      const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

      switch (association.nature) {
        case 'oneWay': {
          return _.set(acc, attribute, _.get(newValue, assocModel.primaryKey, newValue));
        }
        case 'oneToOne': {
          // if value is the same don't do anything
          if (currentValue === newValue) return acc;

          // if the value is null, set field to null on both sides
          if (_.isNull(newValue)) {
            const updatePromise = assocModel.updateOne(
              {
                [assocModel.primaryKey]: getValuePrimaryKey(currentValue, assocModel.primaryKey),
              },
              { [details.via]: null },
              { session }
            );

            relationUpdates.push(updatePromise);
            return _.set(acc, attribute, null);
          }

          // set old relations to null
          const updateLink = this.updateOne(
            { [attribute]: new mongoose.Types.ObjectId(newValue) },
            { [attribute]: null },
            { session }
          ).then(() => {
            return assocModel.updateOne(
              {
                [this.primaryKey]: new mongoose.Types.ObjectId(newValue),
              },
              { [details.via]: primaryKeyValue },
              { session }
            );
          });

          // set new relation
          relationUpdates.push(updateLink);
          return _.set(acc, attribute, newValue);
        }
        case 'oneToMany': {
          // set relation to null for all the ids not in the list
          const attributeIds = currentValue;
          const toRemove = _.differenceWith(attributeIds, newValue, (a, b) => {
            return `${a[assocModel.primaryKey] || a}` === `${b[assocModel.primaryKey] || b}`;
          });

          const updatePromise = assocModel
            .updateMany(
              {
                [assocModel.primaryKey]: {
                  $in: toRemove.map(
                    val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                  ),
                },
              },
              { [details.via]: null },
              { session }
            )
            .then(() => {
              return assocModel.updateMany(
                {
                  [assocModel.primaryKey]: {
                    $in: newValue.map(
                      val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                    ),
                  },
                },
                { [details.via]: primaryKeyValue },
                { session }
              );
            });

          relationUpdates.push(updatePromise);
          return acc;
        }
        case 'manyToOne': {
          return _.set(acc, attribute, _.get(newValue, assocModel.primaryKey, newValue));
        }
        case 'manyWay':
        case 'manyToMany': {
          if (association.dominant) {
            return _.set(
              acc,
              attribute,
              newValue ? newValue.map(val => val[assocModel.primaryKey] || val) : newValue
            );
          }

          const updatePromise = assocModel
            .updateMany(
              {
                [assocModel.primaryKey]: {
                  $in: currentValue.map(
                    val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                  ),
                },
              },
              {
                $pull: {
                  [association.via]: new mongoose.Types.ObjectId(primaryKeyValue),
                },
              },
              { session }
            )
            .then(() => {
              return assocModel.updateMany(
                {
                  [assocModel.primaryKey]: {
                    $in: newValue
                      ? newValue.map(
                          val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                        )
                      : newValue,
                  },
                },
                {
                  $addToSet: { [association.via]: [primaryKeyValue] },
                },
                { session }
              );
            });

          relationUpdates.push(updatePromise);
          return acc;
        }
        // media -> model
        case 'manyMorphToMany':
        case 'manyMorphToOne': {
          processManyMorphRelations.call(this, association, entry, newValue, params, session);
          break;
        }
        // model -> media
        case 'oneToManyMorph':
        case 'manyToManyMorph': {
          const { acc: morphAcc, relationUpdates: morphUpdates } = processOneToManyMorphRelations.call(
            this,
            association,
            entry,
            currentValue,
            newValue,
            details,
            session
          );
          Object.assign(acc, morphAcc);
          relationUpdates.push(...morphUpdates);
          break;
        }
        case 'oneMorphToOne':
        case 'oneMorphToMany':
          break;
        default:
      }

      return acc;
    }, {});

    // Update virtuals fields.
    await Promise.all(relationUpdates).then(() =>
      this.updateOne({ [this.primaryKey]: primaryKeyValue }, values, {
        strict: false,
        session,
      })
    );

    const updatedEntity = await this.findOne({
      [this.primaryKey]: primaryKeyValue,
    })
      .session(session)
      .populate(populate);

    return updatedEntity && updatedEntity.toObject ? updatedEntity.toObject() : updatedEntity;
  },

  deleteRelations(entry, { session = null } = {}) {
    const primaryKeyValue = entry[this.primaryKey];

    return Promise.all(
      this.associations.map(async association => {
        const { nature, via, dominant } = association;

        // TODO: delete all the ref to the model

        switch (nature) {
          case 'oneWay':
          case 'manyWay': {
            return;
          }
          case 'oneToMany':
          case 'oneToOne': {
            if (!via) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany({ [via]: primaryKeyValue }, { [via]: null }, { session });
          }
          case 'manyToMany':
          case 'manyToOne': {
            if (!via || dominant) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany(
              { [via]: primaryKeyValue },
              { $pull: { [via]: primaryKeyValue } },
              { session }
            );
          }
          case 'oneToManyMorph':
          case 'manyToManyMorph': {
            // delete relation inside of the ref model

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            // ignore them ghost relations
            if (!targetModel) return;

            const element = {
              ref: primaryKeyValue,
              kind: this.globalId,
              [association.filter]: association.alias,
            };

            return targetModel.updateMany(
              { [via]: { $elemMatch: element } },
              { $pull: { [via]: element } },
              { session }
            );
          }
          case 'manyMorphToMany':
          case 'manyMorphToOne': {
            // delete relation inside of the ref model
            // console.log(entry[association.alias]);

            if (Array.isArray(entry[association.alias])) {
              return Promise.all(
                entry[association.alias].map(val => {
                  const targetModel = strapi.db.getModelByGlobalId(val.kind);

                  // ignore them ghost relations
                  if (!targetModel) return;

                  const field = val[association.filter];
                  const reverseAssoc = targetModel.associations?.find(
                    assoc => assoc.alias === field
                  );

                  if (reverseAssoc?.nature === 'oneToManyMorph') {
                    return targetModel.updateMany(
                      {
                        [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
                      },
                      {
                        [field]: null,
                      },
                      { session }
                    );
                  }

                  return targetModel.updateMany(
                    {
                      [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
                    },
                    {
                      $pull: { [field]: primaryKeyValue },
                    },
                    { session }
                  );
                })
              );
            }

            return;
          }
          case 'oneMorphToOne':
          case 'oneMorphToMany': {
            return;
          }
        }
      })
    );
  },
};

          break;
        }
        default: {
          const natureConditions = [
            'oneToOne',
            'oneWay',
            'manyToOne',
          ];

          resolver[alias] = async (obj, options) => {
            // force component relations to be refetched
            if (model.modelType === 'component') {
              obj[alias] = _.get(obj[alias], targetModel.primaryKey, obj[alias]);
            }

            const loader = strapi.plugins.graphql.services['data-loaders'].loaders[targetModel.uid];

            const localId = obj[model.primaryKey];
            const targetPK = targetModel.primaryKey;
            const foreignId = _.get(obj[alias], targetModel.primaryKey, obj[alias]);

            const params = {
              ...initQueryOptions(targetModel, obj),
              ...convertToParams(_.omit(amountLimiting(options), 'where')),
              ...convertToQuery(options.where),
            };

            if (natureConditions.includes(nature)) {
              if (!_.has(obj, alias) || _.isNil(foreignId)) {
                return null;
              }

              // check this is an entity and not a mongo ID
              if (_.has(obj[alias], targetPK)) {
                return assignOptions(obj[alias], obj);
              }

              const query = {
                single: true,
                filters: {
                  ...params,
                  [targetPK]: foreignId,
                },
              };

              return loader.load(query).then(r => assignOptions(r, obj));
            }

            if (
              nature === 'oneToMany' ||
              (nature === 'manyToMany' && association.dominant !== true)
            ) {
              const { via } = association;

              const filters = {
                ...params,
                [via]: localId,
              };

              return loader.load({ filters }).then(r => assignOptions(r, obj));
            }

            if (
              nature === 'manyWay' ||
              (nature === 'manyToMany' && association.dominant === true)
            ) {
              let targetIds = [];

              // find the related ids to query them and apply the filters
              if (Array.isArray(obj[alias])) {
                targetIds = obj[alias].map(value => value[targetPK] || value);
              } else {
                const entry = await strapi
                  .query(model.uid)
                  .findOne({ [primaryKey]: obj[primaryKey] }, [alias]);

                if (_.isEmpty(entry[alias])) {
                  return [];
                }

                targetIds = entry[alias].map(el => el[targetPK]);
              }

              const filters = {
                ...params,
                [`${targetPK}_in`]: targetIds.map(_.toString),
              };

              return loader.load({ filters }).then(r => assignOptions(r, obj));
            }
          };
          break;
        }
      }

      return resolver;
    }, {});
};

'use strict';

/**
 * Module dependencies
 */

// Public node modules.
const _ = require('lodash');
const mongoose = require('mongoose');

// Utils
const {
  models: { getValuePrimaryKey },
} = require('strapi-utils');

const transformToArrayID = (array, pk) => {
  if (_.isArray(array)) {
    return array
      .map(value => value && (getValuePrimaryKey(value, pk) || value))
      .filter(n => n)
      .map(val => _.toString(val));
  }

  return transformToArrayID([array]);
};

const removeUndefinedKeys = (obj = {}) => _.pickBy(obj, _.negate(_.isUndefined));

const addRelationMorph = async (model, params, { session = null } = {}) => {
  const { id, alias, refId, ref, field, filter } = params;

  await model.updateMany(
    {
      [model.primaryKey]: id,
    },
    {
      $push: {
        [alias]: {
          ref: new mongoose.Types.ObjectId(refId),
          kind: ref,
          [filter]: field,
        },
      },
    },
    { session }
  );
};

const removeRelationMorph = async (model, params, { session = null } = {}) => {
  const { alias } = params;

  let opts;
  // if entry id is provided simply query it
  if (params.id) {
    opts = {
      _id: params.id,
    };
  } else {
    opts = {
      [alias]: {
        $elemMatch: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    };
  }

  await model.updateMany(
    opts,
    {
      $pull: {
        [alias]: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    },
    { session }
  );
};

/**
 * Extracts the ref model and handles morph relation updates for manyMorph associations.
 * @param {Object} association - Association definition
 * @param {Object} entry - Current entry being updated
 * @param {Object} obj - Morph relation object from newValue
 * @param {Object} params - Update parameters including session
 * @returns {Promise<void>}
 */
const handleManyMorphRelation = async (association, entry, obj, params) => {
  const { session } = params;
  const refModel = strapi.db.getModel(obj.ref, obj.source);

  const createRelation = () => addRelationMorph(
    this,
    {
      id: entry[this.primaryKey],
      alias: association.alias,
      ref: obj.kind || refModel.globalId,
      refId: new mongoose.Types.ObjectId(obj.refId),
      field: obj.field,
      filter: association.filter,
    },
    { session }
  );

  const reverseAssoc = refModel.associations?.find(assoc => assoc.alias === obj.field);

  if (reverseAssoc?.nature === 'oneToManyMorph') {
    return Promise.all([
      removeRelationMorph(
        this,
        {
          alias: association.alias,
          ref: obj.kind || refModel.globalId,
          refId: new mongoose.Types.ObjectId(obj.refId),
          field: obj.field,
          filter: association.filter,
        },
        { session }
      ),
      createRelation(),
      refModel.updateMany(
        {
          [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
        },
        {
          [obj.field]: new mongoose.Types.ObjectId(entry[this.primaryKey]),
        },
        { session }
      ),
    ]);
  }

  return createRelation().then(() => {
    return refModel.updateMany(
      {
        [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
      },
      {
        $push: { [obj.field]: new mongoose.Types.ObjectId(entry[this.primaryKey]) },
      },
      { session }
    );
  });
};

/**
 * Handles morph relation updates for oneToManyMorph and manyToManyMorph associations.
 * @param {Object} association - Association definition
 * @param {Object} entry - Current entry being updated
 * @param {Array} newValue - New relation values
 * @param {Object} params - Update parameters including session
 * @returns {Promise<void>}
 */
const handleMorphToManyRelation = async (association, entry, newValue, params) => {
  const { session } = params;
  const { details } = association;
  const model = strapi.db.getModel(details.model || details.collection, details.plugin);

  const currentIds = transformToArrayID(entry[association.alias], this.primaryKey);
  const newIds = transformToArrayID(newValue, this.primaryKey);

  const toAdd = _.difference(newIds, currentIds);
  const toRemove = _.difference(currentIds, newIds);

  const addPromise = Promise.all(
    toAdd.map(id => addRelationMorph(
      model,
      {
        id,
        alias: association.via,
        ref: this.globalId,
        refId: entry._id,
        field: association.alias,
        filter: association.filter,
      },
      { session }
    ))
  );

  const removePromises = toRemove.map(id =>
    removeRelationMorph(
      model,
      {
        id,
        alias: association.via,
        ref: this.globalId,
        refId: entry._id,
        field: association.alias,
        filter: association.filter,
      },
      { session }
    )
  );

  return Promise.all([addPromise, ...removePromises]);
};

/**
 * Handles morph relation deletions for manyMorph associations.
 * @param {Object} association - Association definition
 * @param {Object} entry - Entry being deleted
 * @param {Object} params - Delete parameters including session
 * @returns {Promise<void>}
 */
const deleteManyMorphRelations = async (association, entry, params) => {
  const { session } = params;

  if (!Array.isArray(entry[association.alias])) {
    return;
  }

  return Promise.all(
    entry[association.alias].map(async val => {
      const targetModel = strapi.db.getModelByGlobalId(val.kind);

      if (!targetModel) return;

      const field = val[association.filter];
      const reverseAssoc = targetModel.associations?.find(assoc => assoc.alias === field);

      if (reverseAssoc?.nature === 'oneToManyMorph') {
        return targetModel.updateMany(
          {
            [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
          },
          {
            [field]: null,
          },
          { session }
        );
      }

      return targetModel.updateMany(
        {
          [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
        },
        {
          $pull: { [field]: entry[this.primaryKey] },
        },
        { session }
      );
    })
  );
};

module.exports = {
  async update(params, { session = null } = {}) {
    const relationUpdates = [];
    const populate = this.associations.map(x => x.alias);
    const primaryKeyValue = getValuePrimaryKey(params, this.primaryKey);

    const entry = await this.findOne({ [this.primaryKey]: primaryKeyValue })
      .session(session)
      .populate(populate)
      .lean();

    const values = Object.keys(removeUndefinedKeys(params.values)).reduce((acc, attribute) => {
      const currentValue = entry[attribute];
      const newValue = params.values[attribute];

      const association = this.associations.find(x => x.alias === attribute);

      if (!association) {
        const details = this._attributes[attribute];
        if (_.get(details, 'isVirtual') !== true) {
          return _.set(acc, attribute, newValue);
        }
        return acc;
      }

      const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

      switch (association.nature) {
        case 'oneWay': {
          return _.set(acc, attribute, _.get(newValue, assocModel.primaryKey, newValue));
        }
        case 'oneToOne': {
          if (currentValue === newValue) return acc;

          if (_.isNull(newValue)) {
            const updatePromise = assocModel.updateOne(
              {
                [assocModel.primaryKey]: getValuePrimaryKey(currentValue, assocModel.primaryKey),
              },
              { [details.via]: null },
              { session }
            );
            relationUpdates.push(updatePromise);
            return _.set(acc, attribute, null);
          }

          const updateLink = this.updateOne(
            { [attribute]: new mongoose.Types.ObjectId(newValue) },
            { [attribute]: null },
            { session }
          ).then(() => {
            return assocModel.updateOne(
              {
                [this.primaryKey]: new mongoose.Types.ObjectId(newValue),
              },
              { [details.via]: primaryKeyValue },
              { session }
            );
          });

          relationUpdates.push(updateLink);
          return _.set(acc, attribute, newValue);
        }
        case 'oneToMany': {
          const attributeIds = currentValue;
          const toRemove = _.differenceWith(attributeIds, newValue, (a, b) => {
            return `${a[assocModel.primaryKey] || a}` === `${b[assocModel.primaryKey] || b}`;
          });

          const updatePromise = assocModel
            .updateMany(
              {
                [assocModel.primaryKey]: {
                  $in: toRemove.map(
                    val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                  ),
                },
              },
              { [details.via]: null },
              { session }
            )
            .then(() => {
              return assocModel.updateMany(
                {
                  [assocModel.primaryKey]: {
                    $in: newValue.map(
                      val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                    ),
                  },
                },
                { [details.via]: primaryKeyValue },
                { session }
              );
            });

          relationUpdates.push(updatePromise);
          return acc;
        }
        case 'manyToOne': {
          return _.set(acc, attribute, _.get(newValue, assocModel.primaryKey, newValue));
        }
        case 'manyWay':
        case 'manyToMany': {
          if (association.dominant) {
            return _.set(
              acc,
              attribute,
              newValue ? newValue.map(val => val[assocModel.primaryKey] || val) : newValue
            );
          }

          const updatePromise = assocModel
            .updateMany(
              {
                [assocModel.primaryKey]: {
                  $in: currentValue.map(
                    val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                  ),
                },
              },
              {
                $pull: {
                  [association.via]: new mongoose.Types.ObjectId(primaryKeyValue),
                },
              },
              { session }
            )
            .then(() => {
              return assocModel.updateMany(
                {
                  [assocModel.primaryKey]: {
                    $in: newValue
                      ? newValue.map(
                          val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                        )
                      : newValue,
                  },
                },
                {
                  $addToSet: { [association.via]: [primaryKeyValue] },
                },
                { session }
              );
            });

          relationUpdates.push(updatePromise);
          return acc;
        }
        case 'manyMorphToMany':
        case 'manyMorphToOne': {
          newValue.forEach(obj => {
            relationUpdates.push(
              handleManyMorphRelation.call(this, association, entry, obj, { session })
            );
          });
          break;
        }
        case 'oneToManyMorph':
        case 'manyToManyMorph': {
          relationUpdates.push(
            handleMorphToManyRelation.call(this, association, entry, newValue, { session })
          );
          break;
        }
        case 'oneMorphToOne':
        case 'oneMorphToMany':
          break;
        default:
      }

      return acc;
    }, {});

    await Promise.all(relationUpdates).then(() =>
      this.updateOne({ [this.primaryKey]: primaryKeyValue }, values, {
        strict: false,
        session,
      })
    );

    const updatedEntity = await this.findOne({
      [this.primaryKey]: primaryKeyValue,
    })
      .session(session)
      .populate(populate);

    return updatedEntity && updatedEntity.toObject ? updatedEntity.toObject() : updatedEntity;
  },

  deleteRelations(entry, { session = null } = {}) {
    const primaryKeyValue = entry[this.primaryKey];

    return Promise.all(
      this.associations.map(async association => {
        const { nature, via, dominant } = association;

        switch (nature) {
          case 'oneWay':
          case 'manyWay': {
            return;
          }
          case 'oneToMany':
          case 'oneToOne': {
            if (!via) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany({ [via]: primaryKeyValue }, { [via]: null }, { session });
          }
          case 'manyToMany':
          case 'manyToOne': {
            if (!via || dominant) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany(
              { [via]: primaryKeyValue },
              { $pull: { [via]: primaryKeyValue } },
              { session }
            );
          }
          case 'oneToManyMorph':
          case 'manyToManyMorph': {
            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            if (!targetModel) return;

            const element = {
              ref: primaryKeyValue,
              kind: this.globalId,
              [association.filter]: association.alias,
            };

            return targetModel.updateMany(
              { [via]: { $elemMatch: element } },
              { $pull: { [via]: element } },
              { session }
            );
          }
          case 'manyMorphToMany':
          case 'manyMorphToOne': {
            return deleteManyMorphRelations.call(this, association, entry, { session });
          }
          case 'oneMorphToOne':
          case 'oneMorphToMany': {
            return;
          }
        }
      })
    );
  },
};

const buildAssocResolvers = model => {
  const { primaryKey, associations = [] } = model;

  const isRelationAllowed = association =>
    isNotPrivate(model, association.alias) && isTypeAttributeEnabled(model, association.alias);

  const buildMorphResolver = association => {
    const { alias } = association;
    const targetModel = strapi.getModel(association.target, association.plugin);

    return {
      [alias]: async obj => {
        if (obj[alias]) {
          return assignOptions(obj[alias], obj);
        }

        const params = {
          ...initQueryOptions(targetModel, obj),
          id: obj[primaryKey],
        };

        const entry = await strapi.query(model.uid).findOne(params, [alias]);

        return assignOptions(entry[alias], obj);
      },
    };
  };

  const buildStandardResolver = association => {
    const target = association.model || association.collection;
    const targetModel = strapi.getModel(target, association.plugin);
    const { nature, alias } = association;

    const getLoader = () =>
      strapi.plugins.graphql.services['data-loaders'].loaders[targetModel.uid];

    const resolveOneWay = async (obj, options) => {
      const foreignId = _.get(obj[alias], targetModel.primaryKey, obj[alias]);
      if (!_.has(obj, alias) || _.isNil(foreignId)) return null;

      if (_.has(obj[alias], targetModel.primaryKey)) {
        return assignOptions(obj[alias], obj);
      }

      const query = {
        single: true,
        filters: {
          ...initQueryOptions(targetModel, obj),
          ...convertToQuery(options?.where),
          ...convertToParams(_.omit(amountLimiting(options), 'where')),
          [targetModel.primaryKey]: foreignId,
        },
      };

      return getLoader().load(query).then(r => assignOptions(r, obj));
    };

    const resolveCollection = async (obj, options) => {
      const localId = obj[model.primaryKey];
      const via = association.via;

      const filters = {
        ...initQueryOptions(targetModel, obj),
        ...convertToQuery(options?.where),
        ...convertToParams(_.omit(amountLimiting(options), 'where')),
        [via]: localId,
      };

      return getLoader().load({ filters }).then(r => assignOptions(r, obj));
    };

    const resolveDominantRelation = async (obj, options) => {
      const targetPK = targetModel.primaryKey;

      let targetIds = [];
      if (Array.isArray(obj[alias])) {
        targetIds = obj[alias].map(value => value[targetPK] || value);
      } else {
        const entry = await strapi
          .query(model.uid)
          .findOne({ [primaryKey]: obj[primaryKey] }, [alias]);

        if (_.isEmpty(entry[alias])) return [];

        targetIds = entry[alias].map(el => el[targetPK]);
      }

      const filters = {
        ...initQueryOptions(targetModel, obj),
        ...convertToQuery(options?.where),
        ...convertToParams(_.omit(amountLimiting(options), 'where')),
        [`${targetPK}_in`]: targetIds.map(_.toString),
      };

      return getLoader().load({ filters }).then(r => assignOptions(r, obj));
    };

    const defaultResolver = async (obj, options) => {
      if (model.modelType === 'component') {
        obj[alias] = _.get(obj[alias], targetModel.primaryKey, obj[alias]);
      }

      if (['oneToOne', 'oneWay', 'manyToOne'].includes(nature)) {
        return resolveOneWay(obj, options);
      }

      if (nature === 'oneToMany' || (nature === 'manyToMany' && association.dominant !== true)) {
        return resolveCollection(obj, options);
      }

      if (nature === 'manyWay' || (nature === 'manyToMany' && association.dominant === true)) {
        return resolveDominantRelation(obj, options);
      }

      return null;
    };

    return { [alias]: defaultResolver };
  };

  return associations
    .filter(isRelationAllowed)
    .reduce((resolver, association) => {
      const { nature } = association;

      if (
        nature === 'oneToManyMorph' ||
        nature === 'manyMorphToOne' ||
        nature === 'manyMorphToMany' ||
        nature === 'manyToManyMorph'
      ) {
        return { ...resolver, ...buildMorphResolver(association) };
      }

      return { ...resolver, ...buildStandardResolver(association) };
    }, {});
};

'use strict';

/**
 * Module dependencies
 */

// Public node modules.
const _ = require('lodash');
const mongoose = require('mongoose');

// Utils
const {
  models: { getValuePrimaryKey },
} = require('strapi-utils');

const transformToArrayID = (array, pk) => {
  if (_.isArray(array)) {
    return array
      .map(value => value && (getValuePrimaryKey(value, pk) || value))
      .filter(n => n)
      .map(val => _.toString(val));
  }

  return transformToArrayID([array]);
};

const removeUndefinedKeys = (obj = {}) => _.pickBy(obj, _.negate(_.isUndefined));

const addRelationMorph = async (model, params, { session = null } = {}) => {
  const { id, alias, refId, ref, field, filter } = params;

  await model.updateMany(
    {
      [model.primaryKey]: id,
    },
    {
      $push: {
        [alias]: {
          ref: new mongoose.Types.ObjectId(refId),
          kind: ref,
          [filter]: field,
        },
      },
    },
    { session }
  );
};

const removeRelationMorph = async (model, params, { session = null } = {}) => {
  const { alias } = params;

  let opts;
  // if entry id is provided simply query it
  if (params.id) {
    opts = {
      _id: params.id,
    };
  } else {
    opts = {
      [alias]: {
        $elemMatch: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    };
  }

  await model.updateMany(
    opts,
    {
      $pull: {
        [alias]: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    },
    { session }
  );
};

/**
 * Strategy for handling oneWay associations
 */
const handleOneWay = (acc, association, newValue, assocModel) => {
  return _.set(acc, association.alias, _.get(newValue, assocModel.primaryKey, newValue));
};

/**
 * Strategy for handling oneToOne associations
 */
const handleOneToOne = async (acc, association, currentValue, newValue, details, session, primaryKeyValue) => {
  const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

  if (currentValue === newValue) return acc;

  if (_.isNull(newValue)) {
    const updatePromise = assocModel.updateOne(
      {
        [assocModel.primaryKey]: getValuePrimaryKey(currentValue, assocModel.primaryKey),
      },
      { [details.via]: null },
      { session }
    );
    relationUpdates.push(updatePromise);
    return _.set(acc, association.alias, null);
  }

  const updateLink = this.updateOne(
    { [association.alias]: new mongoose.Types.ObjectId(newValue) },
    { [association.alias]: null },
    { session }
  ).then(() => {
    return assocModel.updateOne(
      {
        [this.primaryKey]: new mongoose.Types.ObjectId(newValue),
      },
      { [details.via]: primaryKeyValue },
      { session }
    );
  });

  relationUpdates.push(updateLink);
  return _.set(acc, association.alias, newValue);
};

/**
 * Strategy for handling oneToMany associations
 */
const handleOneToMany = async (acc, association, currentValue, newValue, details, session, primaryKeyValue) => {
  const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

  const attributeIds = currentValue;
  const toRemove = _.differenceWith(attributeIds, newValue, (a, b) => {
    return `${a[assocModel.primaryKey] || a}` === `${b[assocModel.primaryKey] || b}`;
  });

  const updatePromise = assocModel
    .updateMany(
      {
        [assocModel.primaryKey]: {
          $in: toRemove.map(
            val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
          ),
        },
      },
      { [details.via]: null },
      { session }
    )
    .then(() => {
      return assocModel.updateMany(
        {
          [assocModel.primaryKey]: {
            $in: newValue.map(
              val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
            ),
          },
        },
        { [details.via]: primaryKeyValue },
        { session }
      );
    });

  relationUpdates.push(updatePromise);
  return acc;
};

/**
 * Strategy for handling manyToOne associations
 */
const handleManyToOne = (acc, association, newValue, assocModel) => {
  return _.set(acc, association.alias, _.get(newValue, assocModel.primaryKey, newValue));
};

/**
 * Strategy for handling manyToMany and manyWay associations
 */
const handleManyToManyOrManyWay = async (acc, association, currentValue, newValue, details, session, primaryKeyValue) => {
  const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

  if (association.dominant) {
    return _.set(
      acc,
      association.alias,
      newValue ? newValue.map(val => val[assocModel.primaryKey] || val) : newValue
    );
  }

  const updatePromise = assocModel
    .updateMany(
      {
        [assocModel.primaryKey]: {
          $in: currentValue.map(
            val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
          ),
        },
      },
      {
        $pull: {
          [association.via]: new mongoose.Types.ObjectId(primaryKeyValue),
        },
      },
      { session }
    )
    .then(() => {
      return assocModel.updateMany(
        {
          [assocModel.primaryKey]: {
            $in: newValue
              ? newValue.map(
                  val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                )
              : newValue,
          },
        },
        {
          $addToSet: { [association.via]: [primaryKeyValue] },
        },
        { session }
      );
    });

  relationUpdates.push(updatePromise);
  return acc;
};

/**
 * Strategy for handling manyMorph associations (media -> model)
 */
const handleManyMorph = async (acc, association, newValue, details, session, entry) => {
  newValue.forEach(obj => {
    const refModel = strapi.db.getModel(obj.ref, obj.source);

    const createRelation = () => {
      return addRelationMorph(
        this,
        {
          id: entry[this.primaryKey],
          alias: association.alias,
          ref: obj.kind || refModel.globalId,
          refId: new mongoose.Types.ObjectId(obj.refId),
          field: obj.field,
          filter: association.filter,
        },
        { session }
      );
    };

    const reverseAssoc = refModel.associations.find(assoc => assoc.alias === obj.field);
    if (reverseAssoc && reverseAssoc.nature === 'oneToManyMorph') {
      relationUpdates.push(
        removeRelationMorph(
          this,
          {
            alias: association.alias,
            ref: obj.kind || refModel.globalId,
            refId: new mongoose.Types.ObjectId(obj.refId),
            field: obj.field,
            filter: association.filter,
          },
          { session }
        )
          .then(createRelation)
          .then(() => {
            return refModel.updateMany(
              {
                [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
              },
              {
                [obj.field]: new mongoose.Types.ObjectId(entry[this.primaryKey]),
              },
              { session }
            );
          })
      );
    } else {
      relationUpdates.push(
        createRelation().then(() => {
          return refModel.updateMany(
            {
              [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
            },
            {
              $push: { [obj.field]: new mongoose.Types.ObjectId(entry[this.primaryKey]) },
            },
            { session }
          );
        })
      );
    }
  });
  return acc;
};

/**
 * Strategy for handling morph relations (model -> media)
 */
const handleMorphRelations = async (acc, association, currentValue, newValue, details, session, entry) => {
  const currentIds = transformToArrayID(currentValue, this.primaryKey);
  const newIds = transformToArrayID(newValue, this.primaryKey);

  const toAdd = _.difference(newIds, currentIds);
  const toRemove = _.difference(currentIds, newIds);

  const model = strapi.db.getModel(details.model || details.collection, details.plugin);

  if (!Array.isArray(newValue)) {
    _.set(acc, association.alias, newIds[0]);
  } else {
    _.set(acc, association.alias, newIds);
  }

  const addPromise = Promise.all(
    toAdd.map(id => {
      return addRelationMorph(
        model,
        {
          id,
          alias: association.via,
          ref: this.globalId,
          refId: entry._id,
          field: association.alias,
          filter: association.filter,
        },
        { session }
      );
    })
  );

  relationUpdates.push(addPromise);

  toRemove.forEach(id => {
    relationUpdates.push(
      removeRelationMorph(
        model,
        {
          id,
          alias: association.via,
          ref: this.globalId,
          refId: entry._id,
          field: association.alias,
          filter: association.filter,
        },
        { session }
      )
    );
  });
  return acc;
};

/**
 * Strategy for handling oneMorph associations
 */
const handleOneMorph = () => {
  // No-op for oneMorph associations
};

/**
 * Strategy dispatch table for relation update handling
 */
const relationUpdateStrategies = {
  oneWay: handleOneWay,
  oneToOne: handleOneToOne,
  oneToMany: handleOneToMany,
  manyToOne: handleManyToOne,
  manyWay: handleManyToManyOrManyWay,
  manyToMany: handleManyToManyOrManyWay,
  manyMorphToMany: handleManyMorph,
  manyMorphToOne: handleManyMorph,
  oneToManyMorph: handleMorphRelations,
  manyToManyMorph: handleMorphRelations,
  oneMorphToOne: handleOneMorph,
  oneMorphToMany: handleOneMorph,
};

/**
 * Process relation updates using strategy pattern
 */
const processRelationUpdates = async (acc, association, currentValue, newValue, details, session, entry, primaryKeyValue) => {
  const handler = relationUpdateStrategies[association.nature];
  if (!handler) return acc;

  const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

  if (association.nature === 'oneWay') {
    return handler(acc, association, newValue, assocModel);
  }

  if (association.nature === 'manyToOne') {
    return handler(acc, association, newValue, assocModel);
  }

  if (['manyWay', 'manyToMany'].includes(association.nature)) {
    return handler(acc, association, currentValue, newValue, details, session, primaryKeyValue);
  }

  if (['manyMorphToMany', 'manyMorphToOne'].includes(association.nature)) {
    return handler(acc, association, newValue, details, session, entry);
  }

  if (['oneToManyMorph', 'manyToManyMorph'].includes(association.nature)) {
    return handler(acc, association, currentValue, newValue, details, session, entry);
  }

  if (['oneMorphToOne', 'oneMorphToMany'].includes(association.nature)) {
    return handler();
  }

  return handler(acc, association, currentValue, newValue, details, session, primaryKeyValue);
};

module.exports = {
  async update(params, { session = null } = {}) {
    const relationUpdates = [];
    const populate = this.associations.map(x => x.alias);
    const primaryKeyValue = getValuePrimaryKey(params, this.primaryKey);

    const entry = await this.findOne({ [this.primaryKey]: primaryKeyValue })
      .session(session)
      .populate(populate)
      .lean();

    const values = Object.keys(removeUndefinedKeys(params.values)).reduce((acc, attribute) => {
      const currentValue = entry[attribute];
      const newValue = params.values[attribute];

      const association = this.associations.find(x => x.alias === attribute);

      if (!association) {
        const details = this._attributes[attribute];
        if (_.get(details, 'isVirtual') !== true) {
          return _.set(acc, attribute, newValue);
        }
        return acc;
      }

      const details = this._attributes[attribute];
      return processRelationUpdates(acc, association, currentValue, newValue, details, session, entry, primaryKeyValue);
    }, {});

    await Promise.all(relationUpdates).then(() =>
      this.updateOne({ [this.primaryKey]: primaryKeyValue }, values, {
        strict: false,
        session,
      })
    );

    const updatedEntity = await this.findOne({
      [this.primaryKey]: primaryKeyValue,
    })
      .session(session)
      .populate(populate);

    return updatedEntity && updatedEntity.toObject ? updatedEntity.toObject() : updatedEntity;
  },

  async deleteRelations(entry, { session = null } = {}) {
    const primaryKeyValue = entry[this.primaryKey];

    return Promise.all(
      this.associations.map(async association => {
        const { nature, via, dominant } = association;

        switch (nature) {
          case 'oneWay':
          case 'manyWay': {
            return;
          }
          case 'oneToMany':
          case 'oneToOne': {
            if (!via) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany({ [via]: primaryKeyValue }, { [via]: null }, { session });
          }
          case 'manyToMany':
          case 'manyToOne': {
            if (!via || dominant) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany(
              { [via]: primaryKeyValue },
              { $pull: { [via]: primaryKeyValue } },
              { session }
            );
          }
          case 'oneToManyMorph':
          case 'manyToManyMorph': {
            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            if (!targetModel) return;

            const element = {
              ref: primaryKeyValue,
              kind: this.globalId,
              [association.filter]: association.alias,
            };

            return targetModel.updateMany(
              { [via]: { $elemMatch: element } },
              { $pull: { [via]: element } },
              { session }
            );
          }
          case 'manyMorphToMany':
          case 'manyMorphToOne': {
            if (Array.isArray(entry[association.alias])) {
              return Promise.all(
                entry[association.alias].map(val => {
                  const targetModel = strapi.db.getModelByGlobalId(val.kind);

                  if (!targetModel) return;

                  const field = val[association.filter];
                  const reverseAssoc = targetModel.associations.find(
                    assoc => assoc.alias === field
                  );

                  if (reverseAssoc && reverseAssoc.nature === 'oneToManyMorph') {
                    return targetModel.updateMany(
                      {
                        [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
                      },
                      {
                        [field]: null,
                      },
                      { session }
                    );
                  }

                  return targetModel.updateMany(
                    {
                      [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
                    },
                    {
                      $pull: { [field]: primaryKeyValue },
                    },
                    { session }
                  );
                })
              );
            }

            return;
          }
          case 'oneMorphToOne':
          case 'oneMorphToMany': {
            return;
          }
        }
      })
    );
  },
};

'use strict';

/**
 * Module dependencies
 */

// Public node modules.
const _ = require('lodash');
const mongoose = require('mongoose');

// Utils
const {
  models: { getValuePrimaryKey },
} = require('strapi-utils');

const transformToArrayID = (array, pk) => {
  if (_.isArray(array)) {
    return array
      .map(value => value && (getValuePrimaryKey(value, pk) || value))
      .filter(n => n)
      .map(val => _.toString(val));
  }

  return transformToArrayID([array]);
};

const removeUndefinedKeys = (obj = {}) => _.pickBy(obj, _.negate(_.isUndefined));

const addRelationMorph = async (model, params, { session = null } = {}) => {
  const { id, alias, refId, ref, field, filter } = params;

  await model.updateMany(
    {
      [model.primaryKey]: id,
    },
    {
      $push: {
        [alias]: {
          ref: new mongoose.Types.ObjectId(refId),
          kind: ref,
          [filter]: field,
        },
      },
    },
    { session }
  );
};

const removeRelationMorph = async (model, params, { session = null } = {}) => {
  const { alias } = params;

  let opts;
  // if entry id is provided simply query it
  if (params.id) {
    opts = {
      _id: params.id,
    };
  } else {
    opts = {
      [alias]: {
        $elemMatch: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    };
  }

  await model.updateMany(
    opts,
    {
      $pull: {
        [alias]: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    },
    { session }
  );
};

/**
 * Extractor for relation update logic based on association nature
 */
const createRelationUpdateHandler = (association, acc, entry, params, model) => {
  const { nature } = association;
  const { id: entryId, primaryKey: entryPk } = entry;
  const { session } = params;
  const { details, newValue } = association.target;

  const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

  switch (nature) {
    case 'oneWay': {
      return _.set(acc, association.alias, _.get(newValue, assocModel.primaryKey, newValue));
    }
    case 'oneToOne': {
      const currentValue = association.target.currentValue;
      if (currentValue === newValue) return acc;

      if (_.isNull(newValue)) {
        const updatePromise = assocModel.updateOne(
          {
            [assocModel.primaryKey]: getValuePrimaryKey(currentValue, assocModel.primaryKey),
          },
          { [details.via]: null },
          { session }
        );
        association.relationUpdates.push(updatePromise);
        return _.set(acc, association.alias, null);
      }

      const updateLink = model.updateOne(
        { [association.alias]: new mongoose.Types.ObjectId(newValue) },
        { [association.alias]: null },
        { session }
      ).then(() => {
        return assocModel.updateOne(
          {
            [entryPk]: new mongoose.Types.ObjectId(newValue),
          },
          { [details.via]: entryId },
          { session }
        );
      });

      association.relationUpdates.push(updateLink);
      return _.set(acc, association.alias, newValue);
    }
    case 'oneToMany': {
      const attributeIds = association.target.currentValue;
      const toRemove = _.differenceWith(attributeIds, newValue, (a, b) => {
        return `${a[assocModel.primaryKey] || a}` === `${b[assocModel.primaryKey] || b}`;
      });

      const updatePromise = assocModel
        .updateMany(
          {
            [assocModel.primaryKey]: {
              $in: toRemove.map(
                val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
              ),
            },
          },
          { [details.via]: null },
          { session }
        )
        .then(() => {
          return assocModel.updateMany(
            {
              [assocModel.primaryKey]: {
                $in: newValue.map(
                  val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                ),
              },
            },
            { [details.via]: entryId },
            { session }
          );
        });

      association.relationUpdates.push(updatePromise);
      return acc;
    }
    case 'manyToOne': {
      return _.set(acc, association.alias, _.get(newValue, assocModel.primaryKey, newValue));
    }
    case 'manyWay':
    case 'manyToMany': {
      if (association.dominant) {
        return _.set(
          acc,
          association.alias,
          newValue ? newValue.map(val => assocModel.primaryKey || val) : newValue
        );
      }

      const updatePromise = assocModel
        .updateMany(
          {
            [assocModel.primaryKey]: {
              $in: association.target.currentValue.map(
                val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
              ),
            },
          },
          {
            $pull: {
              [association.via]: new mongoose.Types.ObjectId(entryId),
            },
          },
          { session }
        )
        .then(() => {
          return assocModel.updateMany(
            {
              [assocModel.primaryKey]: {
                $in: newValue
                  ? newValue.map(
                      val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                    )
                  : newValue,
              },
            },
            {
              $addToSet: { [association.via]: [entryId] },
            },
            { session }
          );
        });

      association.relationUpdates.push(updatePromise);
      return acc;
    }
    case 'manyMorphToMany':
    case 'manyMorphToOne': {
      association.target.newValue.forEach(obj => {
        const refModel = strapi.db.getModel(obj.ref, obj.source);
        const createRelation = () => {
          return addRelationMorph(
            model,
            {
              id: entryId,
              alias: association.alias,
              ref: obj.kind || refModel.globalId,
              refId: new mongoose.Types.ObjectId(obj.refId),
              field: obj.field,
              filter: association.filter,
            },
            { session }
          );
        };

        const reverseAssoc = refModel.associations.find(assoc => assoc.alias === obj.field);
        if (reverseAssoc && reverseAssoc.nature === 'oneToManyMorph') {
          const removePromise = removeRelationMorph(
            model,
            {
              alias: association.alias,
              ref: obj.kind || refModel.globalId,
              refId: new mongoose.Types.ObjectId(obj.refId),
              field: obj.field,
              filter: association.filter,
            },
            { session }
          );
          association.relationUpdates.push(
            removePromise
              .then(createRelation)
              .then(() => {
                return refModel.updateMany(
                  {
                    [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
                  },
                  {
                    [obj.field]: new mongoose.Types.ObjectId(entryId),
                  },
                  { session }
                );
              })
          );
        } else {
          association.relationUpdates.push(
            createRelation().then(() => {
              return refModel.updateMany(
                {
                  [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
                },
                {
                  $push: { [obj.field]: new mongoose.Types.ObjectId(entryId) },
                },
                { session }
              );
            })
          );
        }
      });
      break;
    }
    case 'oneToManyMorph':
    case 'manyToManyMorph': {
      const currentIds = transformToArrayID(association.target.currentValue, entryPk);
      const newIds = transformToArrayID(association.target.newValue, entryPk);
      const toAdd = _.difference(newIds, currentIds);
      const toRemove = _.difference(currentIds, newIds);

      const morphModel = strapi.db.getModel(details.model || details.collection, details.plugin);

      if (!Array.isArray(association.target.newValue)) {
        _.set(acc, association.alias, newIds[0]);
      } else {
        _.set(acc, association.alias, newIds);
      }

      const addPromise = Promise.all(
        toAdd.map(id => {
          return addRelationMorph(
            morphModel,
            {
              id,
              alias: association.via,
              ref: model.globalId,
              refId: entry._id,
              field: association.alias,
              filter: association.filter,
            },
            { session }
          );
        })
      );

      association.relationUpdates.push(addPromise);

      toRemove.forEach(id => {
        association.relationUpdates.push(
          removeRelationMorph(
            morphModel,
            {
              id,
              alias: association.via,
              ref: model.globalId,
              refId: entry._id,
              field: association.alias,
              filter: association.filter,
            },
            { session }
          )
        );
      });
      break;
    }
    case 'oneMorphToOne':
    case 'oneMorphToMany':
      break;
    default:
  }

  return acc;
};

/**
 * Process relation updates with decreased complexity by delegating to nature-specific handlers
 */
const processRelationUpdates = (association, acc, entry, params, model) => {
  association.target = {
    currentValue: params.currentValue,
    newValue: params.newValue,
  };
  association.dominant = association.dominant;
  association.relationUpdates = params.relationUpdates;

  return createRelationUpdateHandler(association, acc, entry, params, model);
};

/**
 * Helper to extract association field for deletion logic by nature
 */
const getDeleteHandlerByNature = (association) => {
  const { nature, via, dominant } = association;

  switch (nature) {
    case 'oneWay':
    case 'manyWay': {
      return () => Promise.resolve();
    }
    case 'oneToMany':
    case 'oneToOne': {
      return async ({ targetModel, entryId, session }) => {
        if (!via) return;
        return targetModel.updateMany({ [via]: entryId }, { [via]: null }, { session });
      };
    }
    case 'manyToMany':
    case 'manyToOne': {
      return async ({ targetModel, entryId, session }) => {
        if (!via || dominant) return;
        return targetModel.updateMany(
          { [via]: entryId },
          { $pull: { [via]: entryId } },
          { session }
        );
      };
    }
    case 'oneToManyMorph':
    case 'manyToManyMorph': {
      return async ({ targetModel, association, entryId, session }) => {
        if (!targetModel) return;

        const element = {
          ref: entryId,
          kind: association._model.globalId,
          [association.filter]: association.alias,
        };

        return targetModel.updateMany(
          { [via]: { $elemMatch: element } },
          { $pull: { [via]: element } },
          { session }
        );
      };
    }
    case 'manyMorphToMany':
    case 'manyMorphToOne': {
      return async ({ association, entry, session }) => {
        if (!Array.isArray(entry[association.alias])) return;

        return Promise.all(
          entry[association.alias].map(val => {
            const targetModel = strapi.db.getModelByGlobalId(val.kind);
            if (!targetModel) return Promise.resolve();

            const field = val[association.filter];
            const reverseAssoc = targetModel.associations.find(
              assoc => assoc.alias === field
            );

            if (reverseAssoc && reverseAssoc.nature === 'oneToManyMorph') {
              return targetModel.updateMany(
                {
                  [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
                },
                {
                  [field]: null,
                },
                { session }
              );
            }

            return targetModel.updateMany(
              {
                [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
              },
              {
                $pull: { [field]: val.ref && (val.ref._id || val.ref) },
              },
              { session }
            );
          })
        );
      };
    }
    case 'oneMorphToOne':
    case 'oneMorphToMany': {
      return () => Promise.resolve();
    }
    default:
      return () => Promise.resolve();
  }
};

/**
 * Delete relations by delegating to handlers by nature
 */
const handleDeleteRelations = async (association, entry, { session = null } = {}) => {
  const { nature, via, dominant } = association;

  const targetModel = strapi.db.getModel(
    association.model || association.collection,
    association.plugin
  );

  const handler = getDeleteHandlerByNature(association);
  return handler({
    nature,
    via,
    dominant,
    targetModel,
    entryId: entry[this.primaryKey],
    association,
    entry,
    session,
    _model: this,
  });
};

module.exports = {
  async update(params, { session = null } = {}) {
    const relationUpdates = [];
    const populate = this.associations.map(x => x.alias);
    const primaryKeyValue = getValuePrimaryKey(params, this.primaryKey);

    const entry = await this.findOne({ [this.primaryKey]: primaryKeyValue })
      .session(session)
      .populate(populate)
      .lean();

    // Only update fields which are on this document.
    const values = Object.keys(removeUndefinedKeys(params.values)).reduce((acc, attribute) => {
      const currentValue = entry[attribute];
      const newValue = params.values[attribute];
      const association = this.associations.find(x => x.alias === attribute);
      const details = this._attributes[attribute];

      if (!association && _.get(details, 'isVirtual') !== true) {
        return _.set(acc, attribute, newValue);
      }

      return processRelationUpdates(association, acc, entry, {
        currentValue,
        newValue,
        session,
        relationUpdates
      }, this);
    }, {});

    // Update virtuals fields.
    await Promise.all(relationUpdates).then(() =>
      this.updateOne({ [this.primaryKey]: primaryKeyValue }, values, {
        strict: false,
        session,
      })
    );

    const updatedEntity = await this.findOne({
      [this.primaryKey]: primaryKeyValue,
    })
      .session(session)
      .populate(populate);

    return updatedEntity && updatedEntity.toObject ? updatedEntity.toObject() : updatedEntity;
  },

  async deleteRelations(entry, { session = null } = {}) {
    const primaryKeyValue = entry[this.primaryKey];

    const deletePromises = this.associations.map(async (association) => {
      return handleDeleteRelations.call(this, association, entry, { session });
    });

    return Promise.all(deletePromises).then(results => results.flat());
  },
};

'use strict';

/**
 * Module dependencies
 */

// Public node modules.
const _ = require('lodash');
const mongoose = require('mongoose');

// Utils
const {
  models: { getValuePrimaryKey },
} = require('strapi-utils');

const transformToArrayID = (array, pk) => {
  if (_.isArray(array)) {
    return array
      .map(value => value && (getValuePrimaryKey(value, pk) || value))
      .filter(n => n)
      .map(val => _.toString(val));
  }

  return transformToArrayID([array]);
};

const removeUndefinedKeys = (obj = {}) => _.pickBy(obj, _.negate(_.isUndefined));

const addRelationMorph = async (model, params, { session = null } = {}) => {
  const { id, alias, refId, ref, field, filter } = params;

  await model.updateMany(
    {
      [model.primaryKey]: id,
    },
    {
      $push: {
        [alias]: {
          ref: new mongoose.Types.ObjectId(refId),
          kind: ref,
          [filter]: field,
        },
      },
    },
    { session }
  );
};

const removeRelationMorph = async (model, params, { session = null } = {}) => {
  const { alias } = params;

  let opts;
  // if entry id is provided simply query it
  if (params.id) {
    opts = {
      _id: params.id,
    };
  } else {
    opts = {
      [alias]: {
        $elemMatch: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    };
  }

  await model.updateMany(
    opts,
    {
      $pull: {
        [alias]: {
          ref: params.refId,
          kind: params.ref,
          [params.filter]: params.field,
        },
      },
    },
    { session }
  );
};

/**
 * Process relation for one-way association
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @param {Object} newValue - New value for attribute
 * @param {Object} assocModel - Association model
 * @returns {Object} - Updated accumulator
 */
const processOneWay = (acc, entry, newValue, assocModel) => {
  return _.set(acc, entry.attribute, _.get(newValue, assocModel.primaryKey, newValue));
};

/**
 * Process relation for one-to-one association
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @param {Object} newValue - New value for attribute
 * @param {Object} assocModel - Association model
 * @param {Object} details - Attribute details
 * @param {String} primaryKeyValue - Primary key value
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated accumulator
 */
const processOneToOne = async (acc, entry, newValue, assocModel, details, primaryKeyValue, session) => {
  const currentValue = entry.currentValue;

  if (currentValue === newValue) {
    return acc;
  }

  if (_.isNull(newValue)) {
    const updatePromise = assocModel.updateOne(
      {
        [assocModel.primaryKey]: getValuePrimaryKey(currentValue, assocModel.primaryKey),
      },
      { [details.via]: null },
      { session }
    );

    acc.relationUpdates.push(updatePromise);
    return _.set(acc.accumulator, entry.attribute, null);
  }

  const updateLink = this.updateOne(
    { [entry.attribute]: new mongoose.Types.ObjectId(newValue) },
    { [entry.attribute]: null },
    { session }
  ).then(() => {
    return assocModel.updateOne(
      {
        [this.primaryKey]: new mongoose.Types.ObjectId(newValue),
      },
      { [details.via]: primaryKeyValue },
      { session }
    );
  });

  acc.relationUpdates.push(updateLink);
  return _.set(acc.accumulator, entry.attribute, newValue);
};

/**
 * Process relation for one-to-many association
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @param {Array} newValue - New values for attribute
 * @param {Object} assocModel - Association model
 * @param {Object} details - Attribute details
 * @param {String} primaryKeyValue - Primary key value
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated accumulator
 */
const processOneToMany = async (acc, entry, newValue, assocModel, details, primaryKeyValue, session) => {
  const attributeIds = entry.currentValue;

  const toRemove = _.differenceWith(attributeIds, newValue, (a, b) => {
    return `${a[assocModel.primaryKey] || a}` === `${b[assocModel.primaryKey] || b}`;
  });

  const updatePromise = assocModel
    .updateMany(
      {
        [assocModel.primaryKey]: {
          $in: toRemove.map(
            val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
          ),
        },
      },
      { [details.via]: null },
      { session }
    )
    .then(() => {
      return assocModel.updateMany(
        {
          [assocModel.primaryKey]: {
            $in: newValue.map(
              val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
            ),
          },
        },
        { [details.via]: primaryKeyValue },
        { session }
      );
    });

  acc.relationUpdates.push(updatePromise);
  return acc.accumulator;
};

/**
 * Process relation for many-to-one association
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @param {Object} newValue - New value for attribute
 * @param {Object} assocModel - Association model
 * @returns {Object} - Updated accumulator
 */
const processManyToOne = (acc, entry, newValue, assocModel) => {
  return _.set(acc.accumulator, entry.attribute, _.get(newValue, assocModel.primaryKey, newValue));
};

/**
 * Process relation for many-to-many or many-way association
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @param {Array} newValue - New values for attribute
 * @param {Object} association - Association definition
 * @param {Object} assocModel - Association model
 * @param {String} primaryKeyValue - Primary key value
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated accumulator
 */
const processManyToMany = async (acc, entry, newValue, association, assocModel, primaryKeyValue, session) => {
  if (association.dominant) {
    return _.set(
      acc.accumulator,
      entry.attribute,
      newValue ? newValue.map(val => val[assocModel.primaryKey] || val) : newValue
    );
  }

  const updatePromise = assocModel
    .updateMany(
      {
        [assocModel.primaryKey]: {
          $in: entry.currentValue.map(
            val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
          ),
        },
      },
      {
        $pull: {
          [association.via]: new mongoose.Types.ObjectId(primaryKeyValue),
        },
      },
      { session }
    )
    .then(() => {
      return assocModel.updateMany(
        {
          [assocModel.primaryKey]: {
            $in: newValue
              ? newValue.map(
                  val => new mongoose.Types.ObjectId(val[assocModel.primaryKey] || val)
                )
              : newValue,
          },
        },
        {
          $addToSet: { [association.via]: [primaryKeyValue] },
        },
        { session }
      );
    });

  acc.relationUpdates.push(updatePromise);
  return acc.accumulator;
};

/**
 * Process relation for many-morph associations
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @param {Array} newValue - New values for attribute
 * @param {Object} association - Association definition
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated accumulator
 */
const processManyMorphRelations = async (acc, entry, newValue, association, session) => {
  for (const obj of newValue) {
    const refModel = strapi.db.getModel(obj.ref, obj.source);

    const createRelation = () => {
      return addRelationMorph(
        this,
        {
          id: entry.entry[this.primaryKey],
          alias: association.alias,
          ref: obj.kind || refModel.globalId,
          refId: new mongoose.Types.ObjectId(obj.refId),
          field: obj.field,
          filter: association.filter,
        },
        { session }
      );
    };

    const reverseAssoc = refModel.associations.find(assoc => assoc.alias === obj.field);
    if (reverseAssoc && reverseAssoc.nature === 'oneToManyMorph') {
      acc.relationUpdates.push(
        removeRelationMorph(
          this,
          {
            alias: association.alias,
            ref: obj.kind || refModel.globalId,
            refId: new mongoose.Types.ObjectId(obj.refId),
            field: obj.field,
            filter: association.filter,
          },
          { session }
        )
          .then(createRelation)
          .then(() => {
            return refModel.updateMany(
              {
                [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
              },
              {
                [obj.field]: new mongoose.Types.ObjectId(entry.entry[this.primaryKey]),
              },
              { session }
            );
          })
      );
    } else {
      acc.relationUpdates.push(
        createRelation().then(() => {
          return refModel.updateMany(
            {
              [refModel.primaryKey]: new mongoose.Types.ObjectId(obj.refId),
            },
            {
              $push: { [obj.field]: new mongoose.Types.ObjectId(entry.entry[this.primaryKey]) },
            },
            { session }
          );
        })
      );
    }
  }

  return acc.accumulator;
};

/**
 * Process relation for one-to-many morph and many-to-many morph associations
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @param {Array} newValue - New values for attribute
 * @param {Object} association - Association definition
 * @param {Object} details - Attribute details
 * @param {String} primaryKeyValue - Primary key value
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated accumulator
 */
const processMorphRelations = async (acc, entry, newValue, association, details, primaryKeyValue, session) => {
  const currentIds = transformToArrayID(entry.currentValue, this.primaryKey);
  const newIds = transformToArrayID(newValue, this.primaryKey);

  const toAdd = _.difference(newIds, currentIds);
  const toRemove = _.difference(currentIds, newIds);

  const model = strapi.db.getModel(details.model || details.collection, details.plugin);

  _.set(acc.accumulator, entry.attribute, Array.isArray(newValue) ? newIds : newIds[0]);

  const addPromise = Promise.all(
    toAdd.map(id => {
      return addRelationMorph(
        model,
        {
          id,
          alias: association.via,
          ref: this.globalId,
          refId: entry.entry._id,
          field: association.alias,
          filter: association.filter,
        },
        { session }
      );
    })
  );

  acc.relationUpdates.push(addPromise);

  toRemove.forEach(id => {
    acc.relationUpdates.push(
      removeRelationMorph(
        model,
        {
          id,
          alias: association.via,
          ref: this.globalId,
          refId: entry.entry._id,
          field: association.alias,
          filter: association.filter,
        },
        { session }
      )
    );
  });

  return acc.accumulator;
};

/**
 * Process relation for one-morph associations
 * @param {Object} acc - Accumulator object
 * @param {Object} entry - Current entry
 * @returns {Object} - Updated accumulator
 */
const processOneMorphRelations = (acc, entry) => {
  return acc.accumulator;
};

/**
 * Main update logic parser with reduced complexity
 * @param {Object} acc - Accumulator object
 * @param {Object} association - Association definition
 * @param {Object} entry - Current entry object with attribute, currentValue
 * @param {Object} newValue - New value for attribute
 * @param {Object} assocModel - Association model
 * @param {Object} details - Attribute details
 * @param {String} primaryKeyValue - Primary key value
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated accumulator
 */
const processAssociation = async (acc, association, entry, newValue, assocModel, details, primaryKeyValue, session) => {
  const createAccumulator = () => ({ accumulator: acc, relationUpdates: acc.relationUpdates });

  switch (association.nature) {
    case 'oneWay':
      return processOneWay(createAccumulator(), entry, newValue, assocModel);

    case 'oneToOne':
      return processOneToOne(createAccumulator(), entry, newValue, assocModel, details, primaryKeyValue, session);

    case 'oneToMany':
      return processOneToMany(createAccumulator(), entry, newValue, assocModel, details, primaryKeyValue, session);

    case 'manyToOne':
      return processManyToOne(createAccumulator(), entry, newValue, assocModel);

    case 'manyWay':
    case 'manyToMany':
      return processManyToMany(createAccumulator(), entry, newValue, association, assocModel, primaryKeyValue, session);

    case 'manyMorphToMany':
    case 'manyMorphToOne':
      return processManyMorphRelations(createAccumulator(), entry, newValue, association, session);

    case 'oneToManyMorph':
    case 'manyToManyMorph':
      return processMorphRelations(createAccumulator(), entry, newValue, association, details, primaryKeyValue, session);

    case 'oneMorphToOne':
    case 'oneMorphToMany':
      return processOneMorphRelations(createAccumulator(), entry);

    default:
      return acc;
  }
};

/**
 * Process associations for relation updates
 * @param {Object} params - Update parameters
 * @param {Object} session - Mongoose session
 * @returns {Object} - Updated entity
 */
module.exports = {
  async update(params, { session = null } = {}) {
    const relationUpdates = [];
    const populate = this.associations.map(x => x.alias);
    const primaryKeyValue = getValuePrimaryKey(params, this.primaryKey);

    const entry = await this.findOne({ [this.primaryKey]: primaryKeyValue })
      .session(session)
      .populate(populate)
      .lean();

    const values = Object.keys(removeUndefinedKeys(params.values)).reduce((acc, attribute) => {
      const currentValue = entry[attribute];
      const newValue = params.values[attribute];

      const association = this.associations.find(x => x.alias === attribute);

      const details = this._attributes[attribute];

      if (!association && _.get(details, 'isVirtual') !== true) {
        return _.set(acc, attribute, newValue);
      }

      const assocModel = strapi.db.getModel(details.model || details.collection, details.plugin);

      const associationEntry = {
        attribute,
        currentValue,
        entry,
      };

      return processAssociation({ accumulator: acc, relationUpdates }, association, associationEntry, newValue, assocModel, details, primaryKeyValue, session);
    }, { accumulator: {}, relationUpdates });

    await Promise.all(values.relationUpdates).then(() =>
      this.updateOne({ [this.primaryKey]: primaryKeyValue }, values.accumulator, {
        strict: false,
        session,
      })
    );

    const updatedEntity = await this.findOne({
      [this.primaryKey]: primaryKeyValue,
    })
      .session(session)
      .populate(populate);

    return updatedEntity && updatedEntity.toObject ? updatedEntity.toObject() : updatedEntity;
  },

  deleteRelations(entry, { session = null } = {}) {
    const primaryKeyValue = entry[this.primaryKey];

    return Promise.all(
      this.associations.map(async association => {
        const { nature, via, dominant } = association;

        switch (nature) {
          case 'oneWay':
          case 'manyWay': {
            return;
          }
          case 'oneToMany':
          case 'oneToOne': {
            if (!via) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany({ [via]: primaryKeyValue }, { [via]: null }, { session });
          }
          case 'manyToMany':
          case 'manyToOne': {
            if (!via || dominant) {
              return;
            }

            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            return targetModel.updateMany(
              { [via]: primaryKeyValue },
              { $pull: { [via]: primaryKeyValue } },
              { session }
            );
          }
          case 'oneToManyMorph':
          case 'manyToManyMorph': {
            const targetModel = strapi.db.getModel(
              association.model || association.collection,
              association.plugin
            );

            if (!targetModel) return;

            const element = {
              ref: primaryKeyValue,
              kind: this.globalId,
              [association.filter]: association.alias,
            };

            return targetModel.updateMany(
              { [via]: { $elemMatch: element } },
              { $pull: { [via]: element } },
              { session }
            );
          }
          case 'manyMorphToMany':
          case 'manyMorphToOne': {
            if (Array.isArray(entry[association.alias])) {
              return Promise.all(
                entry[association.alias].map(val => {
                  const targetModel = strapi.db.getModelByGlobalId(val.kind);

                  if (!targetModel) return;

                  const field = val[association.filter];
                  const reverseAssoc = targetModel.associations.find(
                    assoc => assoc.alias === field
                  );

                  if (reverseAssoc && reverseAssoc.nature === 'oneToManyMorph') {
                    return targetModel.updateMany(
                      {
                        [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
                      },
                      {
                        [field]: null,
                      },
                      { session }
                    );
                  }

                  return targetModel.updateMany(
                    {
                      [targetModel.primaryKey]: val.ref && (val.ref._id || val.ref),
                    },
                    {
                      $pull: { [field]: primaryKeyValue },
                    },
                    { session }
                  );
                })
              );
            }

            return;
          }
          case 'oneMorphToOne':
          case 'oneMorphToMany': {
            return;
          }
        }
      })
    );
  },
};

          break;
        }
        default: {
          resolver[alias] = async (obj, options) => {
            // force component relations to be refetched
            if (model.modelType === 'component') {
              obj[alias] = _.get(obj[alias], targetModel.primaryKey, obj[alias]);
            }

            const loader = strapi.plugins.graphql.services['data-loaders'].loaders[targetModel.uid];

            const localId = obj[model.primaryKey];
            const targetPK = targetModel.primaryKey;
            const foreignId = _.get(obj[alias], targetModel.primaryKey, obj[alias]);

            const params = {
              ...initQueryOptions(targetModel, obj),
              ...convertToParams(_.omit(amountLimiting(options), 'where')),
              ...convertToQuery(options.where),
            };

            if (isSingleRelation(nature)) {
              return resolveSingleRelation(obj, alias, targetPK, foreignId, loader, params, model, targetModel, resolverOpts);
            }

            if (isToManyRelation(nature, association)) {
              return resolveToManyRelation(obj, alias, localId, targetPK, loader, params, model, targetModel, association);
            }

            if (isManyWayOrDominantToMany(nature, association)) {
              return resolveManyWayOrDominantToMany(obj, alias, localId, targetPK, loader, params, model, targetModel, association, primaryKey);
            }
          };
          break;
        }
      }

      return resolver;
    }, {});
};

/**
 * Check if nature represents a single relation (oneToOne, oneWay, manyToOne)
 * @param {string} nature
 * @returns {boolean}
 */
const isSingleRelation = nature => ['oneToOne', 'oneWay', 'manyToOne'].includes(nature);

/**
 * Check if nature represents a to-many relation (oneToMany or non-dominant manyToMany)
 * @param {string} nature
 * @param {object} association
 * @returns {boolean}
 */
const isToManyRelation = (nature, association) =>
  nature === 'oneToMany' ||
  (nature === 'manyToMany' && association.dominant !== true);

/**
 * Check if nature represents many-way or dominant many-to-many
 * @param {string} nature
 * @param {object} association
 * @returns {boolean}
 */
const isManyWayOrDominantToMany = (nature, association) =>
  nature === 'manyWay' ||
  (nature === 'manyToMany' && association.dominant === true);

/**
 * Resolve single relation (oneToOne, oneWay, manyToOne)
 * @param {object} obj
 * @param {string} alias
 * @param {string} targetPK
 * @param {any} foreignId
 * @param {object} loader
 * @param {object} params
 * @param {object} model
 * @param {object} targetModel
 * @param {object} resolverOpts
 * @returns {Promise<object|null>}
 */
const resolveSingleRelation = async (obj, alias, targetPK, foreignId, loader, params, model, targetModel, resolverOpts) => {
  if (!_.has(obj, alias) || _.isNil(foreignId)) {
    return null;
  }

  // check this is an entity and not a mongo ID
  if (_.has(obj[alias], targetPK)) {
    return assignOptions(obj[alias], obj);
  }

  const query = {
    single: true,
    filters: {
      ...params,
      [targetPK]: foreignId,
    },
  };

  return loader.load(query).then(r => assignOptions(r, obj));
};

/**
 * Resolve to-many relations (oneToMany or non-dominant manyToMany)
 * @param {object} obj
 * @param {string} alias
 * @param {string} localId
 * @param {string} targetPK
 * @param {object} loader
 * @param {object} params
 * @param {object} model
 * @param {object} targetModel
 * @param {object} association
 * @returns {Promise<Array>}
 */
const resolveToManyRelation = async (obj, alias, localId, targetPK, loader, params, model, targetModel, association) => {
  const { via } = association;

  const filters = {
    ...params,
    [via]: localId,
  };

  return loader.load({ filters }).then(r => assignOptions(r, obj));
};

/**
 * Resolve many-way or dominant many-to-many relations
 * @param {object} obj
 * @param {string} alias
 * @param {string} localId
 * @param {string} targetPK
 * @param {object} loader
 * @param {object} params
 * @param {object} model
 * @param {object} targetModel
 * @param {object} association
 * @param {string} primaryKey
 * @returns {Promise<Array>}
 */
const resolveManyWayOrDominantToMany = async (obj, alias, localId, targetPK, loader, params, model, targetModel, association, primaryKey) => {
  let targetIds = [];

  // find the related ids to query them and apply the filters
  if (Array.isArray(obj[alias])) {
    targetIds = obj[alias].map(value => value[targetPK] || value);
  } else {
    const entry = await strapi
      .query(model.uid)
      .findOne({ [primaryKey]: obj[primaryKey] }, [alias]);

    if (_.isEmpty(entry[alias])) {
      return [];
    }

    targetIds = entry[alias].map(el => el[targetPK]);
  }

  const filters = {
    ...params,
    [`${targetPK}_in`]: targetIds.map(_.toString),
  };

  return loader.load({ filters }).then(r => assignOptions(r, obj));
};

'use strict';

const _ = require('lodash');
const { contentTypes } = require('strapi-utils');

const {
  hasDraftAndPublish,
  constants: { DP_PUB_STATE_LIVE },
} = contentTypes;

const DynamicZoneScalar = require('../types/dynamiczoneScalar');

const { formatModelConnectionsGQL } = require('./build-aggregation');
const types = require('./type-builder');
const {
  actionExists,
  mergeSchemas,
  convertToParams,
  convertToQuery,
  amountLimiting,
  createDefaultSchema,
} = require('./utils');
const { toSDL, getTypeDescription } = require('./schema-definitions');
const { toSingular, toPlural } = require('./naming');
const { buildQuery, buildMutation } = require('./resolvers-builder');

const OPTIONS = Symbol();

const FIND_QUERY_ARGUMENTS = {
  sort: 'String',
  limit: 'Int',
  start: 'Int',
  where: 'JSON',
  publicationState: 'PublicationState',
};

const FIND_ONE_QUERY_ARGUMENTS = {
  id: 'ID!',
  publicationState: 'PublicationState',
};

/**
 * Builds a graphql schema from all the contentTypes & components loaded
 * @param {{ schema: object }} ctx
 * @returns {object}
 */
const buildShadowCrud = ctx => {
  const models = Object.values(strapi.contentTypes).filter(model => model.plugin !== 'admin');
  const components = Object.values(strapi.components);

  const allSchemas = buildModels([...models, ...components], ctx);

  return mergeSchemas(createDefaultSchema(), ...allSchemas);
};

const assignOptions = (element, parent) => {
  if (Array.isArray(element)) {
    return element.map(el => assignOptions(el, parent));
  }

  return _.set(element, OPTIONS, _.get(parent, OPTIONS, {}));
};

const isQueryEnabled = (schema, name) => {
  return _.get(schema, `resolver.Query.${name}`) !== false;
};

const getQueryInfo = (schema, name) => {
  return _.get(schema, `resolver.Query.${name}`, {});
};

const isMutationEnabled = (schema, name) => {
  return _.get(schema, `resolver.Mutation.${name}`) !== false;
};

const getMutationInfo = (schema, name) => {
  return _.get(schema, `resolver.Mutation.${name}`, {});
};

const isTypeAttributeEnabled = (model, attr) =>
  _.get(strapi.plugins.graphql, `config._schema.graphql.type.${model.globalId}.${attr}`) !== false;
const isNotPrivate = _.curry((model, attributeName) => {
  return !contentTypes.isPrivateAttribute(model, attributeName);
});

const wrapPublicationStateResolver = query => async (parent, args, ctx, ast) => {
  const results = await query(parent, args, ctx, ast);

  const queryOptions = _.pick(args, 'publicationState');
  return assignOptions(results, { [OPTIONS]: queryOptions });
};

const buildTypeDefObj = model => {
  const { associations = [], attributes, primaryKey, globalId } = model;

  const typeDef = {
    id: 'ID!',
    [primaryKey]: 'ID!',
  };

  // Add timestamps attributes.
  if (_.isArray(_.get(model, 'options.timestamps'))) {
    const [createdAtKey, updatedAtKey] = model.options.timestamps;
    typeDef[createdAtKey] = 'DateTime!';
    typeDef[updatedAtKey] = 'DateTime!';
  }

  Object.keys(attributes)
    .filter(isNotPrivate(model))
    .filter(attributeName => isTypeAttributeEnabled(model, attributeName))
    .forEach(attributeName => {
      const attribute = attributes[attributeName];
      // Convert our type to the GraphQL type.
      typeDef[attributeName] = types.convertType({
        attribute,
        modelName: globalId,
        attributeName,
      });
    });

  // Change field definition for collection relations
  associations
    .filter(association => association.type === 'collection')
    .filter(association => isNotPrivate(model, association.alias))
    .filter(attributeName => isTypeAttributeEnabled(model, attributeName))
    .forEach(association => {
      typeDef[`${association.alias}(sort: String, limit: Int, start: Int, where: JSON)`] =
        typeDef[association.alias];

      delete typeDef[association.alias];
    });

  return typeDef;
};

const generateEnumDefinitions = (model, globalId) => {
  const { attributes } = model;
  return Object.keys(attributes)
    .filter(attribute => attributes[attribute].type === 'enumeration')
    .filter(attribute => isTypeAttributeEnabled(model, attribute))
    .map(attribute => {
      const definition = attributes[attribute];

      const name = types.convertEnumType(definition, globalId, attribute);
      const values = definition.enum.map(v => `\t${v}`).join('\n');
      return `enum ${name} {\n${values}\n}\n`;
    })
    .join('');
};

const generateDynamicZoneDefinitions = (attributes, globalId, schema) => {
  Object.keys(attributes)
    .filter(attribute => attributes[attribute].type === 'dynamiczone')
    .forEach(attribute => {
      const { components } = attributes[attribute];

      const typeName = `${globalId}${_.upperFirst(_.camelCase(attribute))}DynamicZone`;

      if (components.length === 0) {
        // Create dummy type because graphql doesn't support empty ones
        schema.definition += `type ${typeName} { _:Boolean}`;
      } else {
        const componentsTypeNames = components.map(componentUID => {
          const compo = strapi.components[componentUID];
          if (!compo) {
            throw new Error(
              `Trying to creating dynamiczone type with unkown component ${componentUID}`
            );
          }

          return compo.globalId;
        });

        const unionType = `union ${typeName} = ${componentsTypeNames.join(' | ')}`;

        schema.definition += `\n${unionType}\n`;
      }

      const inputTypeName = `${typeName}Input`;
      schema.definition += `\nscalar ${inputTypeName}\n`;

      schema.resolvers[typeName] = {
        __resolveType(obj) {
          return strapi.components[obj.__component].globalId;
        },
      };

      schema.resolvers[inputTypeName] = new DynamicZoneScalar({
        name: inputTypeName,
        attribute,
        globalId,
        components,
      });
    });
};

const initQueryOptions = (targetModel, parent) => {
  if (hasDraftAndPublish(targetModel)) {
    return {
      _publicationState: _.get(parent, [OPTIONS, 'publicationState'], DP_PUB_STATE_LIVE),
    };
  }

  return {};
};

/**
 * Creates association resolvers for a given model.
 * Handles all relation types: oneToOne, oneWay, manyToOne, oneToMany, manyToMany, manyWay, and morph types.
 */
const buildAssocResolvers = model => {
  const { primaryKey, associations = [] } = model;

  return associations
    .filter(association => isNotPrivate(model, association.alias))
    .filter(association => isTypeAttributeEnabled(model, association.alias))
    .reduce((resolver, association) => {
      const target = association.model || association.collection;
      const targetModel = strapi.getModel(target, association.plugin);
      const { nature, alias } = association;

      if (
        nature === 'oneToManyMorph' ||
        nature === 'manyMorphToOne' ||
        nature === 'manyMorphToMany' ||
        nature === 'manyToManyMorph'
      ) {
        return applyMorphResolver(resolver, alias, model, targetModel, primaryKey);
      }

      return applyRegularResolver(resolver, alias, model, targetModel, nature, associations, primaryKey);
    }, {});
};

const applyMorphResolver = (resolver, alias, model, targetModel, primaryKey) => {
  resolver[alias] = async obj => {
    if (obj[alias]) {
      return assignOptions(obj[alias], obj);
    }

    const params = {
      ...initQueryOptions(targetModel, obj),
      id: obj[primaryKey],
    };

    const entry = await strapi.query(model.uid).findOne(params, [alias]);

    return assignOptions(entry[alias], obj);
  };

  return resolver;
};

/**
 * Applies resolver logic for regular (non-morph) relations.
 */
const applyRegularResolver = (resolver, alias, model, targetModel, nature, associations, primaryKey) => {
  const { via, dominant } = associations.find(a => a.alias === alias) || {};

  resolver[alias] = async (obj, options) => {
    if (model.modelType === 'component') {
      obj[alias] = _.get(obj[alias], targetModel.primaryKey, obj[alias]);
    }

    const loader = strapi.plugins.graphql.services['data-loaders'].loaders[targetModel.uid];

    const localId = obj[model.primaryKey];
    const targetPK = targetModel.primaryKey;
    const foreignId = _.get(obj[alias], targetModel.primaryKey, obj[alias]);

    const params = {
      ...initQueryOptions(targetModel, obj),
      ...convertToParams(_.omit(amountLimiting(options), 'where')),
      ...convertToQuery(options.where),
    };

    if (['oneToOne', 'oneWay', 'manyToOne'].includes(nature)) {
      if (!_.has(obj, alias) || _.isNil(foreignId)) {
        return null;
      }

      if (_.has(obj[alias], targetPK)) {
        return assignOptions(obj[alias], obj);
      }

      const query = {
        single: true,
        filters: {
          ...params,
          [targetPK]: foreignId,
        },
      };

      return loader.load(query).then(r => assignOptions(r, obj));
    }

    if (nature === 'oneToMany' || (nature === 'manyToMany' && !dominant)) {
      const filters = {
        ...params,
        [via]: localId,
      };

      return loader.load({ filters }).then(r => assignOptions(r, obj));
    }

    if (nature === 'manyWay' || (nature === 'manyToMany' && dominant)) {
      const targetIds = Array.isArray(obj[alias])
        ? obj[alias].map(value => value[targetPK] || value)
        : (
          await strapi.query(model.uid).findOne({ [primaryKey]: obj[primaryKey] }, [alias])
        )[alias]?.map(el => el[targetPK]) || [];

      const filters = {
        ...params,
        [`${targetPK}_in`]: targetIds.map(_.toString),
      };

      return loader.load({ filters }).then(r => assignOptions(r, obj));
    }

    return null;
  };

  return resolver;
};

/**
 * Construct the GraphQL query & definition and apply the right resolvers.
 *
 * @return Object
 */
const buildModels = (models, ctx) => {
  return models.map(model => {
    const { kind, modelType } = model;

    if (modelType === 'component') {
      return buildComponent(model);
    }

    switch (kind) {
      case 'singleType':
        return buildSingleType(model, ctx);
      default:
        return buildCollectionType(model, ctx);
    }
  });
};

const buildModelDefinition = (model, globalType = {}) => {
  const { globalId, primaryKey } = model;

  const typeDefObj = buildTypeDefObj(model);

  const schema = {
    definition: '',
    query: {},
    mutation: {},
    resolvers: {
      Query: {},
      Mutation: {},
      [globalId]: {
        id: parent => parent[primaryKey] || parent.id,
        ...buildAssocResolvers(model),
      },
    },
    typeDefObj,
  };

  schema.definition += generateEnumDefinitions(model, globalId);
  generateDynamicZoneDefinitions(model.attributes, globalId, schema);

  const description = getTypeDescription(globalType, model);
  const fields = toSDL(typeDefObj, globalType, model);
  const typeDef = `${description}type ${globalId} {${fields}}\n`;

  schema.definition += typeDef;
  return schema;
};

const buildComponent = component => {
  const { globalId } = component;
  const schema = buildModelDefinition(component);

  schema.definition += types.generateInputModel(component, globalId, {
    allowIds: true,
  });

  return schema;
};

const buildSingleType = (model, ctx) => {
  const { uid, modelName } = model;

  const singularName = toSingular(modelName);

  const globalType = _.get(ctx.schema, `type.${model.globalId}`, {});

  const localSchema = buildModelDefinition(model, globalType);

  if (globalType === false) {
    return localSchema;
  }

  if (isQueryEnabled(ctx.schema, singularName)) {
    const resolverOpts = {
      resolver: `${uid}.find`,
      ...getQueryInfo(ctx.schema, singularName),
    };

    const resolver = buildQuery(singularName, resolverOpts);

    const query = {
      query: {
        [singularName]: {
          args: {
            publicationState: 'PublicationState',
            ...(resolverOpts.args || {}),
          },
          type: model.globalId,
        },
      },
      resolvers: {
        Query: {
          [singularName]: wrapPublicationStateResolver(resolver),
        },
      },
    };

    _.merge(localSchema, query);
  }

  localSchema.definition += types.generateInputModel(model, modelName);

  ['update', 'delete'].forEach(action => {
    const mutationSchema = buildMutationTypeDef({ model, action }, ctx);
    mergeSchemas(localSchema, mutationSchema);
  });

  return localSchema;
};

const buildCollectionType = (model, ctx) => {
  const { plugin, modelName, uid } = model;

  const singularName = toSingular(modelName);
  const pluralName = toPlural(modelName);

  const globalType = _.get(ctx.schema, `type.${model.globalId}`, {});

  const localSchema = buildModelDefinition(model, globalType);
  const { typeDefObj } = localSchema;

  if (globalType === false) {
    return localSchema;
  }

  if (isQueryEnabled(ctx.schema, singularName)) {
    const resolverOpts = {
      resolver: `${uid}.findOne`,
      ...getQueryInfo(ctx.schema, singularName),
    };

    if (actionExists(resolverOpts)) {
      const resolver = buildQuery(singularName, resolverOpts);

      const query = {
        query: {
          [singularName]: {
            args: {
              ...FIND_ONE_QUERY_ARGUMENTS,
              ...(resolverOpts.args || {}),
            },
            type: model.globalId,
          },
        },
        resolvers: {
          Query: {
            [singularName]: wrapPublicationStateResolver(resolver),
          },
        },
      };

      _.merge(localSchema, query);
    }
  }

  if (isQueryEnabled(ctx.schema, pluralName)) {
    const resolverOpts = {
      resolver: `${uid}.find`,
      ...getQueryInfo(ctx.schema, pluralName),
    };

    if (actionExists(resolverOpts)) {
      const resolver = buildQuery(pluralName, resolverOpts);

      const query = {
        query: {
          [pluralName]: {
            args: {
              ...FIND_QUERY_ARGUMENTS,
              ...(resolverOpts.args || {}),
            },
            type: `[${model.globalId}]`,
          },
        },
        resolvers: {
          Query: {
            [pluralName]: wrapPublicationStateResolver(resolver),
          },
        },
      };

      _.merge(localSchema, query);

      if (isQueryEnabled(ctx.schema, `${pluralName}Connection`)) {
        const aggregationSchema = formatModelConnectionsGQL({
          fields: typeDefObj,
          model,
          name: modelName,
          resolver: resolverOpts,
          plugin,
        });

        mergeSchemas(localSchema, aggregationSchema);
      }
    }
  }

  localSchema.definition += types.generateInputModel(model, modelName);

  ['create', 'update', 'delete'].forEach(action => {
    const mutationSchema = buildMutationTypeDef({ model, action }, ctx);
    mergeSchemas(localSchema, mutationSchema);
  });

  return localSchema;
};

/**
 * Builds the mutation type definition for a given model and action.
 */
const buildMutationTypeDef = ({ model, action }, ctx) => {
  const capitalizedName = _.upperFirst(toSingular(model.modelName));
  const mutationName = `${action}${capitalizedName}`;

  const resolverOpts = {
    resolver: `${model.uid}.${action}`,
    transformOutput: result => ({ [toSingular(model.modelName)]: result }),
    ...getMutationInfo(ctx.schema, mutationName),
    isShadowCrud: true,
  };

  if (!actionExists(resolverOpts)) {
    return {};
  }

  const definition = types.generateInputPayloadArguments({
    model,
    name: model.modelName,
    mutationName,
    action,
  });

  if (!isMutationEnabled(ctx.schema, mutationName)) {
    return {
      definition,
    };
  }

  const { kind } = model;
  const args = {};

  if (kind !== 'singleType' || action !== 'delete') {
    Object.assign(args, {
      input: `${mutationName}Input`,
    });
  }

  return {
    definition,
    mutation: {
      [mutationName]: {
        args: {
          ...args,
          ...(resolverOpts.args || {}),
        },
        type: `${mutationName}Payload`,
      },
    },
    resolvers: {
      Mutation: {
        [mutationName]: buildMutation(mutationName, resolverOpts),
      },
    },
  };
};

module.exports = buildShadowCrud;

