      const username =
        body.username || body.nickname || body.name || body.email.split('@')[0];
      const email = body.email || `${username.replace(/\s+/g, '.')}@strapi.io`;

      callback(null, {
        username,
        email,
      });
    });
};

/**
 * Gets CAS profile.
 *
 * @param {string} access_token
 * @param {Object} grant
 * @param {Function} callback
 */
const getCASProfile = (access_token, grant, callback) => {
  const provider_url = 'https://' + _.get(grant['cas'], 'subdomain');
  const cas = purest({
    provider: 'cas',
    config: {
      cas: {
        [provider_url]: {
          __domain: {
            auth: {
              auth: { bearer: '[0]' },
            },
          },
          '{endpoint}': {
            __path: {
              alias: '__default',
            },
          },
        },
      },
    },
  });

  cas
    .query()
    .get('oidc/profile')
    .auth(access_token)
    .request((err, res, body) => {
      if (err) {
        callback(err);
        return;
      }

      const username = getUserNameFromCAS(body);
      const email = getEmailFromCAS(body);

      if (!username || !email) {
        strapi.log.warn(
          'CAS Response Body did not contain required attributes: ' + JSON.stringify(body)
        );
      }

      callback(null, {
        username,
        email,
      });
    });
};

/**
 * Extracts username from CAS response body.
 *
 * @param {Object} body
 * @returns {string|null}
 */
const getUserNameFromCAS = body => {
  if (body.attributes) {
    return body.attributes.strapiusername || body.id || body.sub;
  }
  return body.strapiusername || body.id || body.sub;
};

/**
 * Extracts email from CAS response body.
 *
 * @param {Object} body
 * @returns {string|null}
 */
const getEmailFromCAS = body => {
  if (body.attributes) {
    return body.attributes.strapiemail || body.attributes.email;
  }
  return body.strapiemail || body.email;
};

const buildRedirectUri = (provider = '') =>
  `${getAbsoluteServerUrl(strapi.config)}/connect/${provider}/callback`;

module.exports = {
  connect,
  buildRedirectUri,
};

import { fromJS, List } from 'immutable';
