              }
            )
            .then(() => {
              return assocModel
                .where(
                  assocModel.primaryKey,
                  'in',
                  property.map(val => val[assocModel.primaryKey] || val)
                )
                .save(
                  { [details.via]: primaryKeyValue },
                  {
                    method: 'update',
                    patch: true,
                    require: false,
                    transacting,
                  }
                );
            });

          relationUpdates.push(updatePromise);
          return acc.values;
        }
        case 'manyToOne': {
          acc.values[current] = _.get(property, assocModel.primaryKey, property);
          return acc.values;
        }
        case 'manyWay':
        case 'manyToMany': {
          const storedValue = transformToArrayID(response[current]);
          const currentValue = transformToArrayID(params.values[current]);

          const toAdd = _.difference(currentValue, storedValue);
          const toRemove = _.difference(storedValue, currentValue);

          const collection = this.forge({
            [this.primaryKey]: primaryKeyValue,
          })[association.alias]();

          const updatePromise = collection
            .detach(toRemove, { transacting })
            .then(() => collection.attach(toAdd, { transacting }));

          relationUpdates.push(updatePromise);
          return acc.values;
        }
        case 'manyMorphToMany':
        case 'manyMorphToOne': {
          const handled = await handleMorphToManyUpdate(
            this,
            current,
            { association, values: params.values },
            response,
            { transacting }
          );
          relationUpdates.push(...handled);
          return acc.values;
        }
        case 'oneToManyMorph':
        case 'manyToManyMorph': {
          const handled = await handleOneToManyMorphRelationUpdate(
            this,
            { association, values: params.values, details },
            response,
            { transacting }
          );
          relationUpdates.push(handled);
          return acc.values;
        }
        case 'oneMorphToOne':
        case 'oneMorphToMany': {
          break;
        }
        default:
      }

      return acc.values;
    }, { values: {}, relationUpdates });

    await Promise.all(values.relationUpdates);

    delete values[this.primaryKey];
    if (!_.isEmpty(values)) {
