};

/**
 * Handles file deletion from upload list.
 */
const useHandleClickDeleteFileToUpload = (dispatch, currentStep, goNext) => {
  const handleClickDeleteFileToUpload = useCallback(
    fileIndex => {
      dispatch({
        type: 'REMOVE_FILE_TO_UPLOAD',
        fileIndex,
      });

