  const adminFn = _.get(strapiInstance.admin.config, configPath);
  if (adminFn && typeof adminFn === 'function') {
    try {
      await adminFn();
    } catch (err) {
      strapiInstance.log.error(`${lifecycleName} function in admin failed`);
      strapiInstance.log.error(err);
      strapiInstance.stop();
